Manager::Manager(Profile p,std::string s,std::string stock):impl_(std::make_unique<Impl>(std::move(p),std::move(s),std::move(stock))){}
Manager::~Manager()=default;
bool Manager::alive()noexcept{try{impl_->ensure();return true;}catch(...){impl_->continuous=false;return false;}}
void Manager::disconnect()noexcept{impl_->disconnect();}
const std::string& Manager::name(Unit u)const{return impl_->records.at(index(u)).name;}
std::uint64_t Manager::connection()const noexcept{return impl_->cookie;}
History Manager::history()const{auto unit=[&](Unit which){const auto& r=impl_->records[index(which)];return UnitHistory{r.created,r.referenced,r.initial,r.mount,r.device,r.inode};};return {impl_->cookie,impl_->continuous,impl_->stopped,impl_->restoration,impl_->restorationAccepted,unit(Unit::Owner),unit(Unit::Stock),unit(Unit::Reader),unit(Unit::Fuse)};}

void Manager::retainOwnerAndStock(){impl_->retain(Unit::Owner);auto owner=state(Unit::Owner);need(owner.main==unsigned(getpid())&&owner.active=="active","runtime caller is original owner MainPID");impl_->retain(Unit::Stock);need(stockReady(state(Unit::Stock)),"runtime original healthy stock required");}
void Manager::create(Unit u,const std::vector<std::string>& argv,const std::vector<std::string>& post){impl_->create(u,argv,post);}
recovery::State Manager::state(Unit u){return impl_->state(u);}
UnitProfile Manager::profile(Unit u){return impl_->profile(u);}
bool Manager::verify(){return impl_->verify();}
